def upgrade() -> None:
    conn = op.get_bind()
    for name, field, old, new in UPDATES:
        conn.execute(
            sa.text(f"UPDATE document_template SET {field} = :new WHERE name = :name AND {field} = :old"),
            {"new": new, "name": name, "old": old},
        )
    # Договор купли-продажи — общедоступный пустой бланк.
    conn.execute(sa.text("UPDATE document_template SET is_public = 1 WHERE code = 'sale_contract'"))
    exists = conn.execute(sa.text("SELECT id FROM wiki_page WHERE slug = :s"), {"s": WIKI_SLUG}).first()
    if exists is None:
        conn.execute(
            sa.text("INSERT INTO wiki_page (title, slug, parent_id, body, is_internal, created_at) "
                    "VALUES (:t, :s, NULL, :b, 0, :at)"),
            {"t": WIKI_TITLE, "s": WIKI_SLUG, "b": WIKI_BODY, "at": dt.datetime.utcnow()},
        )


def downgrade() -> None:
    conn = op.get_bind()
    for name, field, old, new in UPDATES:
        conn.execute(
            sa.text(f"UPDATE document_template SET {field} = :old WHERE name = :name AND {field} = :new"),
            {"new": new, "name": name, "old": old},
        )
    conn.execute(sa.text("DELETE FROM wiki_page WHERE slug = :s AND body = :b"), {"s": WIKI_SLUG, "b": WIKI_BODY})
